// src/App.js
import React, { useState } from 'react';
import CodeEditor from './components/CodeEditor';
import './App.css';

function App() {
    // State to track the selected programming language
    const [language, setLanguage] = useState('javascript');
    // State to track the code inside the editor
    const [code, setCode] = useState('// Write your code here...');
    // State to track the execution output
    const [output, setOutput] = useState('');

    return (
        <div className="ide-container">
            {/* Header contains the language selector and run button */}
            <header className="header">
                <h2>eLearning IDE</h2>
                <div className="controls">
                    <select 
                        value={language} 
                        onChange={(e) => setLanguage(e.target.value)}
                    >
                        {/* Languages our app will support */}
                        <option value="javascript">JavaScript</option>
                        <option value="html">HTML/CSS/JS</option>
                        <option value="python">Python</option>
                        <option value="java">Java</option>
                        <option value="c">C</option>
                    </select>
                    <button onClick={() => alert('Run function coming in next step!')}>
                        Run Code
                    </button>
                </div>
            </header>

            {/* Main content splits the screen into Editor and Output */}
            <div className="main-content">
                <CodeEditor 
                    language={language === 'html' ? 'html' : language} 
                    code={code} 
                    setCode={setCode} 
                />

                <div className="output-section">
                    <h3>Output</h3>
                    <div className="output-box">
                        {output || "Click 'Run Code' to see the output here."}
                    </div>
                </div>
            </div>
        </div>
    );
}

export default App;
